import { buildConfig } from 'payload'
import { mongooseAdapter } from '@payloadcms/db-mongodb'
import { lexicalEditor } from '@payloadcms/richtext-lexical'
import path from 'path'
import { fileURLToPath } from 'url'
import { config } from './config/config'

const filename = fileURLToPath(import.meta.url)
const dirname = path.dirname(filename)

export default buildConfig({
  editor: lexicalEditor(),
  collections: [],
  secret: config.secret,
  typescript: {
    outputFile: path.resolve(dirname, 'payload-types.ts'),
    declare: false,
  },
  db: mongooseAdapter({
    url: config.databaseURI,
  }),
  cors: config.corsCsrfUrls,
  csrf: config.corsCsrfUrls,
  telemetry: false,
  admin: {
    user: {
      slug: 'users',
    },
    components: {
      graphics: {
        Logo: '/components/graphics/Logo',
        Icon: '/components/graphics/Icon',
      },
    },
    meta: {
      icons: [
        {
          rel: 'icon',
          type: 'image/png',
          url: '/icon.svg',
        },
      ],
    },
  },
})

import type { Config } from './createConfig'
import { defaultConfig } from './items/default'
import { stagingConfig } from './items/staging'

export const configs: Record<string, Config> = {
  default: defaultConfig,
  staging: stagingConfig,
}

export const getConfig = (selected?: string) => {
  return configs[selected || 'default']
}

export const config = getConfig()

import { defaultConfig } from './items/default'

export type Config = typeof defaultConfig & {
  secret: string
  databaseURI: string
  corsCsrfUrls: string[]
}

export const createConfig = (config: Partial<Config> & Record<string, unknown>): Config => {
  return { ...defaultConfig, ...config } as Config
}

export const defaultConfig = {
  blockGoogleIndexing: true,
  urls: {
    default: {
      nl: 'http://localhost:4000',
      de: 'http://localhost:4000',
    },
    internal: 'http://localhost:4000',
    cdn: undefined as string | undefined,
  },
  sentry: {
    enabled: false,
    environment: 'development',
    dsn: undefined as string | undefined,
  },
  localization: {
    urls: {
      nl: ['http://app-nl.localhost:3000'],
      de: ['http://app-de.localhost:3000'],
    },
  },
  mapbox: {
    accessToken: 'YOUR_MAPBOX_PUBLIC_TOKEN',
  },
  cache: {
    enabled: true,
