import { type ClassValue, clsx } from 'clsx';

export const cn = (...inputs: ClassValue[]) => {
	return clsx(inputs);
};

export type WithElementRef<T> = T & { ref?: unknown };

export interface Config {
  locale: 'nl' | 'de';
}

export interface User {
  id: string;
  updatedAt: string;
  createdAt: string;
  email: string;
  resetPasswordToken?: string | null;
  resetPasswordExpiration?: string | null;
  salt?: string | null;
  hash?: string | null;
  loginAttempts?: number | null;
  lockUntil?: string | null;
  password?: string | null;
}

import { PayloadSDK } from '@payloadcms/sdk';

export const createPayloadClient = (options: { fetchFn?: typeof fetch; baseUrl?: string; token?: string }) => {
  return new PayloadSDK({
    baseURL: options.baseUrl || '',
    fetch: options.fetchFn,
  });
};

import type { CollectionConfig } from 'payload'

export const Users: CollectionConfig = {
  slug: 'users',
  auth: true,
  admin: {
    useAsTitle: 'email',
  },
  fields: [
    {
      name: 'email',
      type: 'email',
      required: true,
      unique: true,
    },
    {
      name: 'password',
      type: 'password',
      required: true,
    },
    {
      name: 'name',
      type: 'text',
    },
  ],
}

import { mongooseAdapter } from '@payloadcms/db-mongodb'
import { lexicalEditor } from '@payloadcms/richtext-lexical'
import path from 'path'
import { fileURLToPath } from 'url'
import { buildConfig } from 'payload'
import { config } from './config/config'
import { Users } from './collections/Users'

const filename = fileURLToPath(import.meta.url)
const dirname = path.dirname(filename)

export default buildConfig({
  editor: lexicalEditor(),
  collections: [Users],
  secret: config.secret,
  typescript: {
    outputFile: path.resolve(dirname, 'payload-types.ts'),
    declare: false,
  },
  db: mongooseAdapter({
    url: config.databaseURI,
  }),
  cors: config.corsCsrfUrls,
  csrf: config.corsCsrfUrls,
  telemetry: false,
  admin: {
    user: 'users',
    components: {
      graphics: {
        Logo: '/components/graphics/Logo',
        Icon: '/components/graphics/Icon',
      },
    },
    meta: {
      icons: [
        {
          rel: 'icon',
          type: 'image/png',
          url: '/icon.svg',
        },
      ],
    },
  },
})

import type { CollectionConfig } from 'payload'

export const Users: CollectionConfig = {
  slug: 'users',
  auth: true,
  admin: {
    useAsTitle: 'email',
  },
  fields: [
    {
      name: 'email',
      type: 'email',
      required: true,
      unique: true,
    },
    {
      name: 'name',
      type: 'text',
    },
  ],
}

